module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire F = (in[3] & in[2]) | (in[1] & in[0]) | (sel[0] & sel[1]);
    wire G = (sel[0] | in[3]) & ((in[2] ^ in[1]) | (in[0] & sel[0]));
    wire H = (in[3] | in[2] | in[1]) & sel[0] & (in[0] | sel[1]);
    wire I = (sel[0] ^ in[2]) & sel[1] | (in[3] | in[0]);
    wire J0 = sel[0] | (in[2] & (in[1] ^ in[0]));
    wire J1 = in[2] & (in[1] ^ in[0]) | sel[1];
    wire K = (in[3] ^ F) & (sel[0] | G);
    wire L = (G | ((in[3] & in[2]) ^ (in[1] & in[0]))) & (sel[0] | (in[1] ^ in[0]));
    wire M = (sel[1] | J0) & (in[3] | J1) | J1 & in[0] | (G & J0);
    wire N = (G & G) | L & sel[1] | J1 & (in[3] | in[2]) | K | (G & L);
    wire O = ((in[3] | in[2] | in[1]) & sel[0]) | (in[2] & in[1]) | (in[2] & J1) | (in[1] & J1) | (in[1] & sel[0]) | (J0 & sel[1]);
    wire P = L | (sel[1] & G) | (sel[0] & G) | (in[3] & sel[1]) | (in[3] & I) | (in[2] & I) | (in[1] & I) | (in[0] & I);
    wire Q = (in[3] & sel[1]) | (in[3] & I) | (in[2] & I) | (in[1] & I) | (in[0] & I) | (G & I) & (sel[1] | (sel[1] & sel[0]));
    wire S = T | J0;
    wire T = (in[3] ^ sel[1]) | (in[2] ^ sel[1]) | (in[1] ^ sel[1]) | (in[0] ^ sel[1]);
    wire U = (in[3] & in[2]) & sel[1] | (in[1] & in[0]) & sel[1];
    wire V = (in[1] ^ sel[1]) & (in[3] | in[2]);
    wire W = (in[0] & in[1]) & sel[1] | (in[0] & sel[1]);
    wire X = (G & U) | (H & V) | (J1 & W);
    wire Y = (X & in[3]) | (X & in[2]) | (X & in[1]) | (X & in[0]) | X;
    wire Z = (in[3] & sel[1]) | (in[2] & sel[1]) | (in[1] & sel[1]) | (in[0] & sel[1]);
    assign out = (sel[1] & F) | (Z | Y) | (X & sel[0]);
endmodule

