module uart (
    input [1:0] in,
    output [3:0] out
);
    wire a0, a1, a2, a3, a4, a5, a6, a7;

    // First level: Select one of four branches based on in
    assign a0 = in[1] & in[0];
    assign a1 = in[1] & ~in[0];
    assign a2 = ~in[1] & in[0];
    assign a3 = ~in[1] & ~in[0];

    // Second level: Use selected paths to create output
    assign a4 = a0 | a1 | a2 | a3;
    assign a5 = a0 | a1;
    assign a6 = a2 | a3;
    assign a7 = a0 | a3;

    // Final output mixer
    assign out[3] = a0;
    assign out[2] = a1;
    assign out[1] = a2;
    assign out[0] = a3;
endmodule

