module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
  reg [1:0] Q;
  always @(clk or reset) begin
      if (clk) begin
          if (reset) Q <= 2'b10;
          else Q <= 2'b01;
      end
      else begin
          if (reset) Q <= 2'b00;
          else Q <= 2'b11;
      end
  end
  wire [1:0] Qout = {up_request, down_request};

  wire gate_1 = Qout ^ 1'b0;
  wire gate_2 = Qout ^ 1'b1;
  wire mod_diag_1 = (gate_1 & gate_2) | (up_request & down_request);
  wire mod_diag_2 = (gate_1 & gate_2) | (reset & up_request);
  wire mod_diag_3 = (gate_1 & gate_2) | (clk & reset);
  wire and_gate = ((((down_request) | (up_request & down_request)) & (reset & up_request)) &
                   ((clk) | (reset & clk)));
  wire a = (and_gate & gate_1) | gate_2;
  wire b = (and_gate & gate_1) | gate_2;
  state = {b, a};
endmodule

